choose.otherwise:
SELECT COUNT(*) > 0 # 그외 통합고객 간주
FROM integrated_customer
WHERE integrated_customer_id = #{customerId}

mapper.select:
SELECT cr.report_url
FROM customer_report cr
WHERE cr.customer_id = #{customerId}
  AND cr.conversion_status_code = #{conversionStatusCode}
ORDER BY cr.created_at DESC, cr.id DESC
LIMIT 1
